const fs = require('fs');
const path = require('path');

const SOURCE = path.join(__dirname, 'README.md');
const TARGET = path.join(__dirname, 'INDEX.md');
const HEADING = /^(#{1,6})(\s+.*)?$/;
const FENCE = /^(```|~~~)/;
const ENDPOINT = /https?:\/\/\S+/;

function stripFrontMatter(lines) {
  if (lines[0] !== undefined && lines[0].trim() === '---') {
    const end = lines.findIndex((line, i) => i > 0 && line.trim() === '---');
    if (end !== -1) return lines.slice(end + 1);
  }
  return lines;
}

function extractHeadings(markdown) {
  const lines = stripFrontMatter(markdown.split(/\r?\n/));
  const headings = [];
  let inFence = false;

  for (const raw of lines) {
    const line = raw.replace(/\s+$/, '');
    const trimmed = line.trim();

    if (FENCE.test(trimmed)) {
      inFence = !inFence;
      continue;
    }
    if (inFence) continue;

    const match = HEADING.exec(trimmed);
    if (match) headings.push(line);
  }

  return headings;
}

function renderIndex(headings) {
  return headings.length === 0 ? '' : headings.join('\n') + '\n';
}

function readHeadingsFromTarget() {
  if (!fs.existsSync(TARGET)) return [];
  return fs
    .readFileSync(TARGET, 'utf8')
    .split(/\r?\n/)
    .filter((line) => line.trim() !== '');
}

function findEndpoint(markdown) {
  const match = ENDPOINT.exec(markdown);
  return match ? match[0] : null;
}

async function checkEndpoint(url) {
  if (!url) {
    console.log('completion check: no local endpoint found in README.md');
    return true;
  }
  try {
    const res = await fetch(url, { signal: AbortSignal.timeout(3000) });
    const body = (await res.text()).trim();
    console.log(`completion check: ${url} -> ${res.status} ${body}`);
    return res.ok;
  } catch (error) {
    console.log(`completion check: ${url} -> unreachable (${error.message})`);
    return false;
  }
}

async function main() {
  const markdown = fs.readFileSync(SOURCE, 'utf8');
  const headings = extractHeadings(markdown);

  fs.writeFileSync(TARGET, renderIndex(headings), 'utf8');

  const written = readHeadingsFromTarget();
  const matches =
    written.length === headings.length && written.every((line, i) => line === headings[i]);

  console.log(`headings found: ${headings.length}`);
  for (const heading of headings) console.log(`  ${heading}`);
  console.log(`wrote ${path.relative(process.cwd(), TARGET)}`);
  console.log(matches ? 'verify: PASS' : 'verify: FAIL');

  const endpointOk = await checkEndpoint(findEndpoint(markdown));

  if (!matches) process.exit(1);
  if (!endpointOk) process.exit(2);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

